-- Database Supabase Export SFY
DROP TABLE IF EXISTS messages CASCADE;
DROP TABLE IF EXISTS songs CASCADE;
DROP TABLE IF EXISTS users CASCADE;

CREATE TABLE songs (
    id SERIAL PRIMARY KEY,
    spotify_id VARCHAR(255) NOT NULL UNIQUE,
    title VARCHAR(255) NOT NULL,
    artist VARCHAR(255) NOT NULL,
    cover_url TEXT NOT NULL,
    meaning TEXT DEFAULT NULL,
    spotify_url TEXT NOT NULL,
    preview_url TEXT DEFAULT NULL,
    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
);

CREATE TABLE users (
    id SERIAL PRIMARY KEY,
    username VARCHAR(100) NOT NULL UNIQUE,
    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
);

CREATE TABLE messages (
    id SERIAL PRIMARY KEY,
    user_id INT DEFAULT 0,
    song_id INT NOT NULL,
    recipient_name VARCHAR(100) NOT NULL,
    sender_name VARCHAR(100) DEFAULT NULL,
    message TEXT NOT NULL,
    lyric_excerpt VARCHAR(280) DEFAULT NULL,
    lyric_section VARCHAR(30) DEFAULT NULL,
    clip_start INT DEFAULT 0,
    images TEXT DEFAULT NULL,
    slug VARCHAR(255) NOT NULL UNIQUE,
    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT fk_messages_songs FOREIGN KEY (song_id) REFERENCES songs(id) ON DELETE CASCADE
);


-- Makna spesifik untuk seluruh lagu yang sudah dipakai oleh pesan publik.
UPDATE songs SET meaning = '"Garis Terdepan" adalah janji untuk tetap hadir sebagai pelindung dan penyemangat, bahkan ketika perasaan tidak bisa dimiliki sepenuhnya. Tokohnya memilih berdiri di barisan paling depan saat orang yang ia sayangi menghadapi kesulitan, tanpa menjadikan cintanya sebagai tuntutan.' WHERE spotify_id = '6JNoIVtIVFTKTwEMk5uHGh';
UPDATE songs SET meaning = 'Lagu ini membayangkan dua orang yang ingin kabur dari rumah dan tekanan hidup untuk mencari kebebasan bersama. Imaji perjalanan mobil dan kemungkinan mati bersama bukan romantisasi kematian, melainkan cara ekstrem untuk menyatakan bahwa kebersamaan terasa lebih berharga daripada hidup dalam keterasingan.' WHERE spotify_id = '0WQiDwKJclirSYG9v5tayI';
UPDATE songs SET meaning = '"Akhir Tak Bahagia" memotret rindu pada seseorang yang pernah diyakini bisa menemani hari-hari sulit. Kenangan tentang mata, tawa, dan malam berbintang membuat perpisahan terasa dekat; pada akhirnya, lagu ini memilih menerima bahwa pertemuan yang berarti pun dapat berakhir tanpa menjadi milik satu sama lain.' WHERE spotify_id = '0BYoWATcndOBcsCfKdTKRx';
UPDATE songs SET meaning = 'Ditulis untuk Toy Story 5, lagu ini berbicara tentang mengenali kembali ikatan lama setelah jarak dan waktu memisahkan. Dari sudut pandang yang dapat dibaca sebagai Jessie, pertemuan itu menghidupkan lagi keyakinan bahwa hubungan yang tulus tidak benar-benar hilang meski sempat terasa selesai.' WHERE spotify_id = '5uPaqMMt59KGrdKIitDRqa';
UPDATE songs SET meaning = '"Usai Di Sini" adalah keputusan sadar untuk berhenti menunggu cinta yang sudah tidak memberi ruang. Tokohnya mengakui mimpi bersama telah direnggut, lalu memilih mengakhiri hubungan sebelum kenangan baik berubah menjadi luka yang lebih pahit.' WHERE spotify_id = '6i5sIqE4lglanzlXXl8gCj';
UPDATE songs SET meaning = '"Melepasmu" tidak sekadar tentang putus cinta: tokohnya menyadari kedekatan yang dijalani lahir ketika ia masih terikat dan sedang bermasalah dengan pasangan lain. Karena tak ingin orang ketiga terus terluka, ia memilih pergi sambil mendoakan orang itu menemukan pendamping yang benar-benar bisa hadir.' WHERE spotify_id = '60ENzjgcc6MpFD883FjqPS';
UPDATE songs SET meaning = '"perayaan mati rasa" menggambarkan fase setelah patah hati ketika kecewa sudah begitu sering datang sampai rasa sakitnya tidak lagi meledak. Kata “perayaan” dipakai secara ironis: bukan pesta bahagia, melainkan usaha menerima kebas, sepi, dan sisa perasaan agar hidup dapat diteruskan.' WHERE spotify_id = '1RyqmamAZTAB9WSZpX4S3f';
UPDATE songs SET meaning = '"Simpan Saja" adalah pengakuan cinta yang sengaja tidak diucapkan karena tokohnya tahu perasaan itu tidak akan membawa mereka ke hubungan yang mungkin. Ia memilih menyimpan rasa dan kenangannya sendiri, bukan memaksa jawaban atau mengganggu kehidupan orang yang dicintai.' WHERE spotify_id = '1SQsMiTpXb6X8fP6tiXfLs';
UPDATE songs SET meaning = '"Tunjuk Satu Bintang" memakai bintang sebagai penanda harapan di tengah hidup yang terasa gelap dan membingungkan. Lagu ini mengajak seseorang memilih satu arah kecil untuk dipercaya, lalu menjadikannya pegangan saat semua hal lain terasa jauh.' WHERE spotify_id = '6pOmOGrSIPy2MEdQ9riRHF';
UPDATE songs SET meaning = '"Buat Aku Tersenyum" adalah ungkapan syukur pada kehadiran sederhana seseorang yang mampu memulihkan hari buruk. Yang dicari tokohnya bukan cinta yang dramatis, melainkan kedekatan yang membuatnya merasa aman, diterima, dan punya alasan untuk tersenyum lagi.' WHERE spotify_id = '6fp5H6JgnlAnS69SktBhpg';
UPDATE songs SET meaning = 'Dalam "My Everything", Glenn Fredly menempatkan pasangan sebagai pusat ketenangan dan arah hidupnya. Versi live ini menegaskan pengakuan yang intim: sosok tersebut bukan pelengkap sesaat, melainkan alasan untuk percaya pada komitmen dan masa depan bersama.' WHERE spotify_id = '6EOj79FjFybJsek78CIQK5';
UPDATE songs SET meaning = '"You Are My Everything" adalah deklarasi cinta yang melihat pasangan sebagai rumah emosional: tempat kembali ketika hidup melelahkan sekaligus sumber keberanian untuk menatap masa depan. Kolaborasi dengan Red memperkuat nuansa dialog dua orang yang sama-sama menegaskan pilihan untuk saling menjaga.' WHERE spotify_id = '2MdoXFLKNUnTdgWZisagEp';

