INSERT INTO songs (id, spotify_id, title, artist, cover_url, meaning, spotify_url, preview_url) VALUES (26, '2hHeGD57S0BcopfVcmehdl', 'Hati-Hati di Jalan', 'Tulus', 'https://i.scdn.co/image/ab67616d0000b273d34a0632f6861e8875d6899b', 'Kisah perpisahan dua insan yang semula saling mencintai dan sejalan, namun akhirnya harus berpisah arah dengan rasa rela.', 'https://open.spotify.com/track/2hHeGD57S0BcopfVcmehdl', 'https://audio-ssl.itunes.apple.com/itunes-assets/AudioPreview116/v4/23/d1/56/23d156c9-75e1-2ce4-6b41-b3b250eb6f72/mzaf_8966903188186794785.plus.aac.p.m4a') ON CONFLICT (id) DO UPDATE SET meaning = EXCLUDED.meaning, preview_url = EXCLUDED.preview_url;
